// Two modules of one package, each with a class `Base` that has a constructor.
// A package's symbols carry its prefix, so the clash is within the package.
import { two } from "./other";

class Base {
  x: i32 = 0;

  constructor(x: i32) {
    this.x = x;
  }
}

export const make = (): i32 => new Base(two()).x;
